import sys; sys.path.insert(0,'.'); from lib import *
d=load_base(); y=labels()
M=lambda l: d[f'mean_hidden_L{l}'][:,KEEP]
def anchor_cv(X, y, a, b, k=10, seeds=(0,), lams=(0.01,0.1,1), nanc=768, cos=False):
    res={lam:[] for lam in lams}
    for s in seeds:
        f=folds(y,k,s); S={lam:np.zeros((len(y),8)) for lam in lams}
        for i in range(k):
            tr=f!=i; te=f==i
            mu=X[tr].mean(0); Z=X-mu; 
            if cos: Z=Z/np.linalg.norm(Z,axis=1,keepdims=True)
            else: Z=Z/np.sqrt((Z[tr]**2).sum(1).mean())
            rng=np.random.RandomState(i+100*s); A=Z[tr][rng.choice(tr.sum(),nanc,replace=False)]
            F=np.tanh(a*(Z@A.T)+b)
            for lam in lams:
                W,bb=ridge_fit(F[tr],y[tr],lam); S[lam][te]=F[te]@W+bb
        for lam in lams: res[lam].append((S[lam].argmax(1)==y).mean())
    return {lam:round(float(np.mean(v)),4) for lam,v in res.items()}
